#include <bits/stdc++.h>
using namespace std;

struct NumberTheory {
    struct Mod998 {
        static const long long MOD = 998244353;
        long long inv(long long a) {
            return pow_mod(a, MOD - 2);
        }
        long long pow_mod(long long base, long long exp) {
            long long result = 1;
            long long cur = base % MOD;
            while (exp > 0) {
                if (exp & 1) result = (result * cur) % MOD;
                cur = (cur * cur) % MOD;
                exp >>= 1;
            }
            return result;
        }
        long long add(long long a, long long b) {
            long long res = a + b;
            if (res >= MOD) res -= MOD;
            return res;
        }
        long long subtract(long long a, long long b) {
            long long res = a - b;
            if (res < 0) res += MOD;
            return res;
        }
        long long mult(long long a, long long b) {
            return (a * b) % MOD;
        }
        long long smallInv(long long a) {
            return inv(a);
        }
        long long ncr(long long n, long long r) {
            if (r > n || r < 0) return 0;
            long long numerator = 1;
            long long denominator = 1;
            for (long long i = 1; i <= r; i++) {
                numerator = mult(numerator, n - i + 1);
                denominator = mult(denominator, i);
            }
            return mult(numerator, inv(denominator));
        }
    };
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string line;
    getline(cin, line);
    istringstream iss(line);
    int n, m;
    iss >> n >> m;

    NumberTheory::Mod998 mod;

    // Compute modular inverse of n + m
    long long sum_nm = n + m;
    long long inv_sum_nm = mod.smallInv(sum_nm);

    long long phaseSize = 1;
    long long p = 1;
    for (int i = 0; p != 0; i++) {
        p = mod.mult(p, n - i);
        p = mod.mult(p, mod.smallInv(n + m - i));
        phaseSize = mod.add(phaseSize, p);
    }

    long long answer = 0;
    for (int k = 1; k <= n; k++) {
        long long term = mod.mult(mod.ncr(n, k), m + k);
        term = mod.mult(term, mod.smallInv(k));
        term = mod.mult(term, phaseSize);
        if (k % 2 == 1)
            answer = mod.add(answer, term);
        else
            answer = mod.subtract(answer, term);
    }
    cout << answer << "\n";
    return 0;
}

